const listTimeline = `-- name: ListTimeline :many
SELECT p.id, p.owner_id, p.sha256, p.mime, p.size, p.width, p.height, p.taken_at, p.exif, p.status, p.error, p.visibility, p.created_at, p.deleted_at, p.original_name, p.preview_format, p.sort_at, p.updated_at, p.purged_at, p.camera, p.lens, p.preview_version, p.duration, p.has_motion, p.content_identifier, p.live_photo_id
FROM photos p
WHERE (p.owner_id = $1
       OR ($2::boolean AND p.status = 'ready'
           AND (photo_shared_directly(p, $1::bigint) OR photo_in_visible_album(p, $1::bigint))))
  AND p.deleted_at IS NULL
  AND p.live_photo_id IS NULL
  AND ($3::timestamptz IS NULL
       OR (p.sort_at, p.id) < ($3::timestamptz, $4::bigint))
  AND ($5::timestamptz IS NULL OR p.sort_at >= $5::timestamptz)
  AND ($6::timestamptz IS NULL OR p.sort_at < $6::timestamptz)
  AND ($7::bigint IS NULL
       OR EXISTS (SELECT 1 FROM album_photos ap WHERE ap.photo_id = p.id AND ap.album_id = $7::bigint))
  AND ($8::bigint[] IS NULL
       OR (p.owner_id = $1
           AND EXISTS (SELECT 1 FROM photo_tags pt WHERE pt.photo_id = p.id AND pt.tag_id = ANY ($8::bigint[]))))
  AND ($9::text[] IS NULL OR p.camera = ANY ($9::text[]))
  AND ($10::text[] IS NULL OR p.lens = ANY ($10::text[]))
  AND ($11::text[] IS NULL OR photo_kind(p.mime, p.has_motion) = ANY ($11::text[]))
ORDER BY p.sort_at DESC, p.id DESC
LIMIT $12
`

type ListTimelineParams struct {
	OwnerID     int64
	WithShared  bool
	AfterSortAt *time.Time
	AfterID     *int64
	FromTime    *time.Time
	ToTime      *time.Time
	AlbumID     *int64
	TagIds      []int64
	Cameras     []string
	Lenses      []string
	Kinds       []string
	MaxRows     int32
}

// The photos of one owner: the current user, or the owner of an album the
// user can see. With with_shared, which the API allows only without an album,
// the list also takes other users' processed photos that the current user can
// see, as photo_visible_to does. Tags are personal, so a tag filter keeps only
// the owner's photos: another user's tag must not reveal how that user grouped
// the photos it shared. The queries below take the same filters.
func (q *Queries) ListTimeline(ctx context.Context, arg ListTimelineParams) ([]Photo, error) {
	rows, err := q.db.Query(ctx, listTimeline,
		arg.OwnerID,
		arg.WithShared,
		arg.AfterSortAt,
		arg.AfterID,
		arg.FromTime,
		arg.ToTime,
		arg.AlbumID,
		arg.TagIds,
		arg.Cameras,
		arg.Lenses,
		arg.Kinds,
		arg.MaxRows,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []Photo
	for rows.Next() {
		var i Photo
		if err := rows.Scan(
			&i.ID,
			&i.OwnerID,
			&i.Sha256,
			&i.Mime,
			&i.Size,
			&i.Width,
			&i.Height,
			&i.TakenAt,
			&i.Exif,
			&i.Status,
			&i.Error,
			&i.Visibility,
			&i.CreatedAt,
			&i.DeletedAt,
			&i.OriginalName,
			&i.PreviewFormat,
			&i.SortAt,
			&i.UpdatedAt,
			&i.PurgedAt,
			&i.Camera,
			&i.Lens,
			&i.PreviewVersion,
			&i.Duration,
			&i.HasMotion,
			&i.ContentIdentifier,
			&i.LivePhotoID,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

